import { date, integer, pgTable, text } from "drizzle-orm/pg-core";

export const users = pgTable("users", {
  id: integer().primaryKey().generatedAlwaysAsIdentity(),
  email: text().notNull().unique(),
  name: text().notNull(),
  createdAt: date("created_at", { mode: "string" }).notNull().defaultNow(),
});

export type UserRow = typeof users.$inferSelect;
export type NewUserRow = typeof users.$inferInsert;
EOF
cat > src/db/index.ts <<'EOF'
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import * as schema from "./schema";

// Reuse the connection across hot reloads in dev.
const globalForDb = globalThis as unknown as { pg?: postgres.Sql };

function connect() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set (see .env.example)");
  return postgres(url);
}

let db: ReturnType<typeof drizzle<typeof schema>> | undefined;

export function getDb() {
  globalForDb.pg ??= connect();
  db ??= drizzle(globalForDb.pg, { schema });
  return db;
}
EOF
cat > src/db/migrate.ts <<'EOF'
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";

const url = process.env.DATABASE_URL;
if (!url) throw new Error("DATABASE_URL is not set (see .env.example)");

const client = postgres(url, { max: 1 });
await migrate(drizzle(client), { migrationsFolder: "./drizzle" });
await client.end();
console.log("migrations applied");
EOF
cat > src/db/seed.ts <<'EOF'
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import { users } from "./schema";

const url = process.env.DATABASE_URL;
if (!url) throw new Error("DATABASE_URL is not set (see .env.example)");

const client = postgres(url, { max: 1 });
await drizzle(client)
  .insert(users)
  .values([
    { email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
    { email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
  ])
  .onConflictDoNothing();
await client.end();
console.log("seeded");
EOF
cat > src/lib/users.ts <<'EOF'
import { asc, eq } from "drizzle-orm";
import { getDb } from "@/db";
import { users } from "@/db/schema";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

function toUser(row: typeof users.$inferSelect): User {
  return { ...row, id: String(row.id) };
}

export async function listUsers(): Promise<User[]> {
  const rows = await getDb().select().from(users).orderBy(asc(users.id));
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  // ids are 32-bit integers; anything else cannot exist
  if (!/^\d{1,9}$/.test(id)) return undefined;
  const [row] = await getDb().select().from(users).where(eq(users.id, Number(id)));
  return row && toUser(row);
}

// TODO: there is no real session handling yet — the dashboard just picks the first user.
export async function getCurrentUser(): Promise<User | undefined> {
  const [row] = await getDb().select().from(users).orderBy(asc(users.id)).limit(1);
  return row && toUser(row);
}
EOF
cat > drizzle.config.ts <<'EOF'
import { defineConfig } from "drizzle-kit";

export default defineConfig({
  dialect: "postgresql",
  schema: "./src/db/schema.ts",
  out: "./drizzle",
  dbCredentials: { url: process.env.DATABASE_URL ?? "" },
});
EOF
cat > .env.example <<'EOF'
# Copy to .env.local and adjust.
DATABASE_URL=postgres://app:change-me@localhost:5432/app
EOF
cat > docker-compose.yml <<'EOF'
services:
  db:
    image: postgres:17
    environment:
      POSTGRES_USER: app
      POSTGRES_PASSWORD: change-me
      POSTGRES_DB: app
    ports:
      - "5432:5432"
    volumes:
      - pgdata:/var/lib/postgresql/data
volumes:
  pgdata:
EOF
